const state={story:'',locs:[],timing:null,symptom:null,trigger:null,activity:null,safety:null,provider:null,existing:'none',home:'',stability:null,wrist:7,components:{support:true,cold:true,topical:true},substitutions:{cold:false,topical:false},budget:null};
const marketing=document.getElementById('marketing'),app=document.getElementById('app'),solution=document.getElementById('solution'),checkout=document.getElementById('checkout');
const screens=[...document.querySelectorAll('.screen')],prog=document.getElementById('prog');
const steps={describe:7,heard:14,localize:22,timing:30,symptom:38,trigger:45,activity:52,safety:61,provider:68,providerInfo:68,existing:75,existingBrace:75,homeRemedy:75,mobility:84,size:92,working:98,stop:61};
function rail(stage){document.querySelectorAll('.railStep').forEach(x=>x.classList.toggle('active',x.dataset.rail===stage))}
function stageFor(id){if(['describe','heard','localize','timing','symptom','trigger','activity'].includes(id))return id==='describe'||id==='heard'?'describe':'narrow';if(['safety','provider','providerInfo','existing','existingBrace','homeRemedy','mobility','size'].includes(id))return'constraints';if(id==='working')return'compare';return'describe'}
function show(id){screens.forEach(x=>x.classList.toggle('active',x.id===id));prog.style.width=(steps[id]||20)+'%';rail(stageFor(id));window.scrollTo({top:0,behavior:'smooth'})}
function start(){marketing.style.display='none';solution.classList.remove('active');checkout.classList.remove('active');app.classList.add('active');show('describe')}
document.querySelectorAll('[data-start]').forEach(b=>b.addEventListener('click',start));document.querySelectorAll('[data-home]').forEach(b=>b.addEventListener('click',()=>{app.classList.remove('active');marketing.style.display='block';window.scrollTo(0,0)}));
function openModal(id){document.getElementById(id)?.classList.add('show')}function closeModals(){document.querySelectorAll('.modalBack.show').forEach(x=>x.classList.remove('show'))}
document.addEventListener('click',e=>{const mb=e.target.closest('[data-modal]');if(mb){openModal(mb.dataset.modal);return}if(e.target.matches('[data-close]')||e.target.classList.contains('modalBack')){closeModals();return}const ans=e.target.closest('[data-answer]');if(ans){document.getElementById(ans.dataset.answer).classList.toggle('show');return}const loc=e.target.closest('[data-loc]');if(loc){const v=loc.dataset.loc;const i=state.locs.indexOf(v);if(i>=0)state.locs.splice(i,1);else state.locs.push(v);loc.classList.toggle('selected',state.locs.includes(v));document.getElementById('locNext').disabled=!state.locs.length;return}const tune=e.target.closest('[data-tune]');if(tune){handleTune(tune.dataset.tune);return}const smart=e.target.closest('[data-smart]');if(smart){applySet(smart.dataset.set);show(nextMissing());return}const go=e.target.closest('[data-go]');if(go){applySet(go.dataset.set);show(go.dataset.go);return}});
function applySet(str){if(!str)return;const [k,v]=str.split(':');state[k]=v;if(k==='existing'&&v==='cold'){state.components.cold=true;state.substitutions.cold=true}if(k==='existing'&&v==='topical'){state.components.topical=true;state.substitutions.topical=true}}
const story=document.getElementById('story'),storyNext=document.getElementById('storyNext');story.addEventListener('input',()=>storyNext.disabled=story.value.trim().length<5);
function interpretStory(text){const t=text.toLowerCase();state.locs=[];if(/\bthumb\b|base of (my |the )?thumb/.test(t))state.locs.push('thumb');if(/\bwrist\b/.test(t))state.locs.push('wrist');if(/\bfinger/.test(t))state.locs.push('fingers');if(/\bpalm\b|back of (my |the )?hand/.test(t))state.locs.push('palm');const handOnly=/\bhand\b/.test(t)&&state.locs.length===0;if(handOnly)state.locs=[];let n=t.match(/(?:about\s+)?(\d+)\s*(day|days|week|weeks|month|months)/);if(n){if(/week/.test(n[2])&&n[1]==='3')state.timing='3weeks';else if(/day/.test(n[2]))state.timing='days';else state.timing='months'}else if(/three\s+weeks?/.test(t))state.timing='3weeks';if(/ach|sore|tender/.test(t))state.symptom='ache';else if(/sharp|catch/.test(t))state.symptom='sharp';else if(/tingl|numb|burn/.test(t))state.symptom='neuro';if(/grip|twist|pickle|tennis|golf|use it|using it/.test(t))state.trigger='grip';if(/pickle\s*ball/.test(t))state.activity='pickleball';else if(/tennis/.test(t))state.activity='tennis';else if(/golf/.test(t))state.activity='golf';else if(/typing|computer|work/.test(t))state.activity='typing';if(/preserv.*movement|keep.*movement|not.*restrict|don.?t want.*restrict|stay active|keep playing/.test(t))state.stability='flex';updateHeard()}
function locLabel(){if(state.locs.includes('wrist')&&state.locs.includes('thumb'))return'Wrist + thumb';if(state.locs.length===1){return{thumb:'Thumb / base of thumb',wrist:'Wrist',palm:'Palm / back of hand',fingers:'Finger(s)',multiple:'Several areas'}[state.locs[0]]}if(state.locs.length>1)return'Several areas';return'Not clear yet — I’ll ask'}
function timingLabel(){return{days:'A few days','3weeks':'About 3 weeks',months:'More than a month',unknown:'Not sure'}[state.timing]||'Not clear yet — I’ll ask'}
function symptomLabel(){return{ache:'Aching / sore',sharp:'Sharp / catching',neuro:'Burning / tingling / numbness',stiff:'Stiff / swollen',unknown:'Hard to describe'}[state.symptom]||'Not clear yet — I’ll ask'}
function updateHeard(){document.getElementById('heardArea').textContent=locLabel();document.getElementById('heardTiming').textContent=timingLabel();document.getElementById('heardActivity').textContent=state.activity?capitalize(state.activity):'Not clear yet — I’ll ask';document.getElementById('heardSymptom').textContent=symptomLabel()}
function capitalize(s){return s?s.charAt(0).toUpperCase()+s.slice(1):''}
storyNext.addEventListener('click',()=>{state.story=story.value.trim();document.getElementById('storyQuote').textContent='“'+state.story+'”';interpretStory(state.story);show('heard')});
function nextMissing(){if(!state.locs.length)return'localize';if(!state.timing)return'timing';if(!state.symptom)return'symptom';if(!state.trigger)return'trigger';if(!state.activity)return'activity';if(!state.safety)return'safety';if(!state.provider)return'provider';if(!state.existing)return'existing';if(!state.stability)return'mobility';return'size'}
document.getElementById('locNext').addEventListener('click',()=>show(nextMissing()));
const activityInput=document.getElementById('activityInput');activityInput.addEventListener('input',()=>document.getElementById('activityNext').disabled=activityInput.value.trim().length<2);document.getElementById('activityNext').addEventListener('click',()=>{state.activity=activityInput.value.trim();show(nextMissing())});
const homeInput=document.getElementById('homeInput');homeInput.addEventListener('input',()=>document.getElementById('homeNext').disabled=homeInput.value.trim().length<3);document.getElementById('homeNext').addEventListener('click',()=>{state.home=homeInput.value.trim();state.existing='home';if(/ice|cold|frozen/.test(state.home.toLowerCase()))state.substitutions.cold=true;show(nextMissing())});
document.getElementById('sizeNext').addEventListener('click',()=>{state.wrist=parseFloat(document.getElementById('wrist').value||7);buildDecisionMap();show('working')});
function buildDecisionMap(){const m=document.getElementById('decisionMap');const rows=[['You localized it to '+locLabel(),'Wrist + thumb options stay eligible; wrist-only solutions lose ground.'],[timingLabel()+' • '+symptomLabel(),'Supports a conservative support/recovery pathway in this standardized case; it does not establish a diagnosis.'],['Goal: '+capitalize(state.activity||'activity')+' • '+(state.stability==='flex'?'preserve useful movement':'more stabilization'),'Movement priority changes which support architecture wins.'],['Fit: '+state.wrist.toFixed(1)+' inches','Manufacturer sizing becomes a hard fit constraint.']];m.innerHTML=rows.map(r=>`<div class="decisionRow"><div class="decisionInput"><b>What you told me</b>${r[0]}</div><div class="decisionArrow">→</div><div class="decisionEffect"><b>What it changes</b>${r[1]}</div></div>`).join('')}
document.querySelector('[data-solution]').addEventListener('click',()=>{app.classList.remove('active');solution.classList.add('active');rail('solution');refreshSolution();window.scrollTo(0,0)});
function refreshSolution(){document.getElementById('metaLoc').textContent=locLabel();document.getElementById('metaPattern').textContent=timingLabel()+' • '+symptomLabel();document.getElementById('metaActivity').textContent=capitalize(state.activity||'activity');document.getElementById('metaFit').textContent=state.wrist.toFixed(1)+' in • '+(state.stability==='flex'?'movement-first':'stability-first');document.getElementById('coldCard').classList.toggle('hidden',!state.components.cold||state.substitutions.cold);document.getElementById('coldKeepCard').classList.toggle('hidden',!state.components.cold||!state.substitutions.cold);document.getElementById('topicalCard').classList.toggle('hidden',!state.components.topical||state.substitutions.topical);document.getElementById('topicalKeepCard').classList.toggle('hidden',!state.components.topical||!state.substitutions.topical);updateTotal()}
const prices={support:19.99,cold:21,topical:11.99};function total(){return (state.components.support?prices.support:0)+(state.components.cold&&!state.substitutions.cold?prices.cold:0)+(state.components.topical&&!state.substitutions.topical?prices.topical:0)}
function updateTotal(){let paid=(state.components.support?1:0)+(state.components.cold&&!state.substitutions.cold?1:0)+(state.components.topical&&!state.substitutions.topical?1:0);document.getElementById('solutionTotal').textContent='$'+total().toFixed(2);let notes=[];if(state.substitutions.cold)notes.push('using your cold option');if(state.substitutions.topical)notes.push('using your topical');document.getElementById('solutionSummary').textContent=(paid?paid+' purchased component'+(paid===1?'':'s'):'no new products')+' + self-care plan'+(notes.length?' • '+notes.join(' • '):'');const stat=document.getElementById('solutionStatus'),cart=document.getElementById('cartBtn');if(!state.components.support){stat.textContent='Core activity-support goal no longer fully addressed';stat.className='solutionStatus statusWarn';cart.disabled=true;cart.textContent='Rebuild needed before cart'}else{stat.textContent='Complete solution';stat.className='solutionStatus statusGood';cart.disabled=false;cart.textContent='Put what I need in my cart →'}}
function result(msg){const el=document.getElementById('tuneResult'),banner=document.getElementById('adjustBanner');el.innerHTML=msg;el.classList.remove('hidden');banner.innerHTML='<b>Keneflex rebuilt your solution.</b><br>'+msg;banner.classList.remove('hidden');refreshSolution();setTimeout(()=>banner.scrollIntoView({behavior:'smooth',block:'start'}),40)}
function handleTune(action){if(action==='cold-have'){state.components.cold=true;state.substitutions.cold=true;result('<b>KEEP yours.</b> If your cold option is intact, comfortable for this area and can safely perform the same recovery role, Keneflex should use it instead of selling another. Polar is removed from the purchase total.')}else if(action==='topical-have'){state.components.topical=true;state.substitutions.topical=true;result('<b>Use what you already have—if it is appropriate for you and used as directed.</b> Keneflex would verify the product and compatibility before treating it as a substitute. Biofreeze is removed from the purchase total.')}else if(action==='cold-buy'){state.components.cold=true;state.substitutions.cold=false;result('<b>Added back.</b> The Polar wrap is again the recovery purchase in your solution.')}else if(action==='topical-buy'){state.components.topical=true;state.substitutions.topical=false;result('<b>Added back.</b> Biofreeze is again the optional comfort purchase in your solution.')}else if(action==='topical-remove'){state.components.topical=false;state.substitutions.topical=false;result('<b>Removed.</b> The topical is a comfort component, not a requirement for the core support + self-care strategy. The solution remains coherent without it.')}else if(action==='cold-remove'){state.components.cold=false;state.substitutions.cold=false;result('<b>Removed.</b> Keneflex can keep the primary support + self-care strategy and not force a recovery purchase you do not value. If you later want a cold option, it can be added without reopening the support decision.')}else if(action==='cold-home'||action==='home-eval'){const v=(document.getElementById('tuneHome').value||state.home||'').trim();if(/ice|cold|frozen/.test(v.toLowerCase())){state.components.cold=true;state.substitutions.cold=true;document.getElementById('coldKeepName').textContent=v?'Use your home cold method':'Use the cold option you already have';result('<b>Your home cold method can potentially fill the recovery role.</b> Keneflex would confirm safe application details; for this prototype, the purchased Polar wrap is removed rather than dismissing the home option.')}else{result('<b>I can’t confirm that this replaces the recovery role from what I know yet.</b> Keneflex should ask one more question rather than automatically approve or reject a home remedy.')}}else if(action==='budget'){let b=parseFloat(document.getElementById('budgetInput').value||0);if(!b){result('Enter a maximum amount so Keneflex can rebuild around it.');return}state.budget=b;state.components.support=true;state.substitutions.cold=false;state.substitutions.topical=false;if(b>=52.98){state.components.cold=true;state.components.topical=true;result('<b>No change needed.</b> The complete three-product solution fits the budget you gave.')}else if(b>=40.99){state.components.cold=true;state.components.topical=false;result('<b>Rebuilt to fit your budget.</b> I kept the primary support and recovery wrap, removed the optional topical, and kept the self-care plan.')}else if(b>=19.99){state.components.cold=false;state.components.topical=false;result('<b>Essentials-first solution.</b> I protected the primary support that satisfies the activity/fit requirements, removed the purchased recovery and topical components, and kept the no-cost self-care plan. I would rather do that than substitute an inadequate cheaper support.')}else{state.components.cold=false;state.components.topical=false;result('<b>Your budget is below the current primary support price.</b> I would not quietly swap in a poorer-fitting option just to hit the number. Keneflex should either find an independently adequate lower-cost support or tell you it cannot meet both constraints yet.')}}else if(action==='support-have'){result('<b>I would evaluate yours before selling another.</b> Type, fit, condition, wear and remaining function matter. If it clears those checks, KEEP should beat a new sale.')}else if(action==='support-no'){state.components.support=false;result('<b>This changes the strategy, not just the cart.</b> The selected support is the core component for the “keep playing with useful movement” goal. If you do not want any support, Keneflex should rebuild the plan around that preference rather than pretend the remaining add-ons solve the same problem.')}closeModals()}
document.getElementById('cartBtn').addEventListener('click',()=>{solution.classList.remove('active');checkout.classList.add('active');renderCart();window.scrollTo(0,0)});
function renderCart(){let rows='';if(state.components.support)rows+=cartRow('https://www.neo-g.com/cdn/shop/files/722-13-Box_R_1080x.png?v=1725268865','Neo G Airflow Wrist & Thumb Support','Medium • Qty 1',prices.support);if(state.components.cold){if(state.substitutions.cold)rows+=cartKeep('Cold recovery component','Use the suitable option you already have','KEEP');else rows+=cartRow('https://trkmedicalproducts.com/cdn/shop/products/41_999x.jpg?v=1626891716','Polar Soft Ice Wrist Wrap','Universal • Qty 1',prices.cold)}if(state.components.topical){if(state.substitutions.topical)rows+=cartKeep('Topical comfort component','Use the suitable product you already have','KEEP');else rows+=cartRow('https://biofreeze.com/static/a06132b8965c43644a3e10fc5aae7a80/7b187/en-US-bf_retailgeltubegreen.png','Biofreeze Pain Relief Gel','Menthol 4% • prototype snapshot',prices.topical)}rows+=`<div class="cartrow"><div class="careCartIcon">✓</div><div><div class="cartname">Keneflex self-care plan</div><div class="cartmeta">Load modification • gentle mobility • recovery • reassessment triggers</div></div><div class="cartprice">Included</div></div>`;document.getElementById('cartRows').innerHTML=rows;document.getElementById('cartTotal').textContent='$'+total().toFixed(2)}
function cartRow(src,name,meta,price){return`<div class="cartrow"><img src="${src}" alt=""><div><div class="cartname">${name}</div><div class="cartmeta">${meta}</div></div><div class="cartprice">$${price.toFixed(2)}</div></div>`}function cartKeep(name,meta,label){return`<div class="cartrow"><div class="careCartIcon">✓</div><div><div class="cartname">${name}</div><div class="cartmeta">${meta}</div></div><div class="cartprice">${label}</div></div>`}
document.addEventListener('error',e=>{if(e.target&&e.target.tagName==='IMG'){const img=e.target,p=img.parentElement,label=img.dataset.fallback;if(label&&p){const bits=label.split('|');p.innerHTML='<div class="fallbackProduct"><b>'+bits[0]+'</b><span>'+(bits[1]||'Product image unavailable')+'</span></div>'}else img.style.opacity='.15'}},true);